/* @lc app=leetcode id=2463 lang=kotlin */ class Solution { fun minimumTotalDistance(robot: List<Int>, factory: Array<IntArray>): Long = robot.sorted().let { r -> factory.sortedBy { it[0] }.fold(LongArray(r.size + 1) { if (it == 0) 0L else Long.MAX_VALUE / 4 }) { dp, (p, c) -> r.runningFold(0L) { s, x -> s + Math.abs(x - p) }.let { pc -> LongArray(r.size + 1) { i -> (0..minOf(c, i)).minOf { t -> dp[i - t] + pc[i] - pc[i - t] } } } }.last() } }